insert into platform_modules(code,title,is_active) values ('36-page-templates','مدیریت قالب‌های صفحات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده قالب‌ها','modules:36-page-templates:read'),('write','ساخت و ویرایش قالب','modules:36-page-templates:write'),('delete','حذف قالب','modules:36-page-templates:delete'),('publish','انتشار قالب','modules:36-page-templates:publish'),('disable','غیرفعال‌سازی قالب','modules:36-page-templates:disable'),('duplicate','تکثیر قالب','modules:36-page-templates:duplicate'),('version','مدیریت نسخه قالب','modules:36-page-templates:version')) v(a,t,p) where m.code='36-page-templates' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;