select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('template-code','کد قالب','text',true,10,'{}'),('template-title','عنوان قالب','text',true,20,'{}'),('template-key','کلید قالب','text',true,30,'{}'),('template-type','نوع قالب','select',true,40,'{"options":["عمومی","داشبورد","فرود","اطلاعاتی","سازمانی","فهرست","جزئیات","سفارشی"]}'),('layout-mode','الگوی چیدمان','select',true,50,'{"options":["تمام‌عرض","دو ستونه","سه ستونه","سایدبار راست","سایدبار چپ","سفارشی"]}'),('header-mode','هدر','select',true,60,'{"options":["استاندارد","فشرده","بدون هدر","سفارشی"]}'),('footer-mode','فوتر','select',true,70,'{"options":["استاندارد","فشرده","بدون فوتر","سفارشی"]}'),('block-definition-reference','مرجع تعریف بلوک‌ها','text',false,80,'{}'),('responsive-mode','رفتار ریسپانسیو','select',true,90,'{"options":["خودکار","موبایل‌محور","دسکتاپ‌محور","سفارشی"]}'),('version','نسخه','number',true,100,'{}'),('status','وضعیت','select',true,110,'{"options":["پیش‌نویس","فعال","غیرفعال","آرشیو شده"]}'),('published-at','تاریخ انتشار','datetime',false,120,'{}'),('owner','مالک قالب','text',false,130,'{}'),('description','توضیحات','textarea',false,140,'{}'),('notes','یادداشت','textarea',false,150,'{}')
) v(k,t,ft,r,s,o) where m.code='36-page-templates' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
